pub(super) const EXECUTE_BACKGROUND_SCRIPT_DESC: &str = r##"Executes server-side JavaScript the way Scripts - Background does. Use for complex GlideRecord operations the CRUD tools cannot express. By default (wait: true) the script is POSTed once to the instance's /sys.scripts.do processor as the authenticated user, and the response is parsed into success/failure, output lines, errors, the scope it ran in, and links to its Script Execution History and rollback context. Requires the admin role. A rollback context is recorded by default (record_for_rollback), so the run's record changes can be rolled back from that context. The processor runs in the authenticated user's own session, so that user's current update set is expected to capture tracked configuration writes, and `scope` picks the application scope. The script request is never retried: a timeout, 5xx, or dropped connection is reported as an unknown outcome (check Script Execution History; do not re-run blindly). When the processor provably did not run the script (HTTP 401/403/404, a login page, or a connection error before sending), the call reports that the script was NOT run. The sys_trigger fallback is opt-in (allow_trigger_fallback or HAPPY_MCP_ALLOW_TRIGGER_FALLBACK=1); when used, the response says so. The sys_trigger path (that fallback, or wait: false) runs in the scheduler's own session, not the caller's: tracked configuration writes may be captured into the Default update set (verify sys_update_xml and move rows with SN-Move-Records-To-Update-Set), GlideUpdateSet calls in it cannot change the update set other tools or the UI use (use SN-Set-Update-Set), and no rollback context is recorded. As a fallback it polls syslog for a correlation marker and reports "completed", "failed", or "timeout" (not a success); wait: false returns only trigger scheduling metadata immediately (see issue #40)."##;
pub(super) const EXECUTE_BACKGROUND_SCRIPT_SCHEMA: &str = r##"{"properties":{"allow_trigger_fallback":{"description":"Allow the sys_trigger fallback when the /sys.scripts.do processor refuses the script (401/403/not authorized). The fallback runs the script as a scheduled job in the scheduler's session: no rollback context is recorded and tracked configuration writes may be captured into the Default update set. Default: false, unless the server sets HAPPY_MCP_ALLOW_TRIGGER_FALLBACK=1. An explicit false overrides the environment.","type":"boolean"},"description":{"description":"Why the script is being run (optional). Flattened to one line and appended to the script as a trailing comment, so it is recorded on the run's Script Execution History record.","type":"string"},"instance":{"description":"Configured ServiceNow instance name. Optional; uses the current instance when omitted.","type":"string"},"record_for_rollback":{"default":true,"description":"Record a rollback context so the run's record changes can be reverted (default true). Applies to the /sys.scripts.do path only.","type":"boolean"},"scope":{"description":"Application scope to run in: an application sys_id, a scope name (e.g. \"x_acme_app\"), or \"global\" (optional; the processor default applies when omitted). Unknown scopes are rejected before anything runs. Only supported with wait: true; a non-global scope also rules out the sys_trigger fallback.","maxLength":100,"type":"string"},"script":{"description":"JavaScript code to execute (required)","type":"string"},"wait":{"default":true,"description":"If true (default), run through /sys.scripts.do and return the parsed result. If false, schedule a sys_trigger job and return immediately with only trigger scheduling metadata (fire-and-forget).","type":"boolean"}},"required":["script"],"type":"object"}"##;
pub(super) const CREATE_FIX_SCRIPT_DESC: &str = r##"⚠️ CREATES (not executes) a fix script file for MANUAL execution. ServiceNow REST API does NOT support direct script execution. This tool generates a .js file in /scripts/ directory with full instructions and optional auto-delete flag. You MUST manually copy and run the script in ServiceNow UI: System Definition → Scripts - Background. Use for: linking UI Policy Actions, setting update sets, complex GlideRecord operations that cannot be done via REST API."##;
pub(super) const CREATE_FIX_SCRIPT_SCHEMA: &str = r##"{"properties":{"auto_delete":{"default":false,"description":"If true, script file will be deleted after you confirm execution (default: false)","type":"boolean"},"description":{"description":"Description of what the script does (optional)","type":"string"},"instance":{"description":"Configured ServiceNow instance name. Optional; uses the current instance when omitted.","type":"string"},"script_content":{"description":"JavaScript code content (required)","type":"string"},"script_name":{"description":"Base name for the script file, without path or extension: 1-100 letters, digits, \".\", \"_\" or \"-\", starting with a letter or digit, and not a Windows device name such as CON, NUL, COM1 or LPT1 (e.g., \"link_ui_policy_actions\") (required)","pattern":"^[A-Za-z0-9][A-Za-z0-9._-]{0,99}$","type":"string"}},"required":["script_name","script_content"],"type":"object"}"##;
