pub(super) const CREATE_WORKFLOW_DESC: &str = r##"Create a complete ServiceNow workflow with activities, transitions, and conditions. This tool orchestrates the entire workflow creation process: base workflow → version → activities → transitions → publish. Reports progress during creation. Limits: 100 activities, 200 transitions, 262144 bytes per script, 4194304 bytes total; the whole input is validated before any write."##;
pub(super) const CREATE_WORKFLOW_SCHEMA: &str = r##"{"properties":{"activities":{"description":"Array of activity definitions","items":{"properties":{"activity_definition_sys_id":{"description":"Activity type sys_id (optional)","pattern":"^[0-9a-f]{32}$","type":"string"},"id":{"description":"Optional unique reference used by transitions and start_activity","maxLength":255,"type":"string"},"name":{"description":"Activity name","maxLength":255,"type":"string"},"script":{"description":"JavaScript code to execute","maxLength":262144,"type":"string"}},"required":["name"],"type":"object"},"maxItems":100,"type":"array"},"condition":{"description":"Condition for workflow to trigger (e.g., \"state=1^priority=1\") (optional)","maxLength":262144,"type":"string"},"description":{"description":"Workflow description (optional)","type":"string"},"instance":{"description":"Configured ServiceNow instance name. Optional; uses the current instance when omitted.","type":"string"},"name":{"description":"Workflow name (required)","maxLength":255,"type":"string"},"progress":{"default":true,"description":"Report progress notifications (default: true)","type":"boolean"},"publish":{"default":false,"description":"Publish workflow after creation (default: false)","type":"boolean"},"table":{"description":"Table this workflow runs against (e.g., \"incident\", \"change_request\")","pattern":"^[A-Za-z0-9_]{1,80}$","type":"string"},"transitions":{"description":"Array of transition definitions (connects activities)","items":{"properties":{"condition_script":{"description":"JavaScript condition (optional)","maxLength":262144,"type":"string"},"from":{"description":"From activity: a declared activity id, a unique activity name, or an existing activity sys_id","maxLength":255,"type":"string"},"to":{"description":"To activity: a declared activity id, a unique activity name, or an existing activity sys_id","maxLength":255,"type":"string"}},"required":["from","to"],"type":"object"},"maxItems":200,"type":"array"}},"required":["name","table","activities"],"type":"object"}"##;
