pub(super) const MOVE_RECORDS_TO_UPDATE_SET_DESC: &str = r##"Move sys_update_xml records to a different update set. Supports filtering by sys_ids, time range, or source update set. Extremely useful when records end up in wrong update set (e.g., "Default" instead of custom set). Reports progress during move operation."##;
pub(super) const MOVE_RECORDS_TO_UPDATE_SET_SCHEMA: &str = r##"{"properties":{"instance":{"description":"Configured ServiceNow instance name. Optional; uses the current instance when omitted.","type":"string"},"progress":{"default":true,"description":"Report progress notifications (default: true)","type":"boolean"},"record_sys_ids":{"description":"Array of at most 200 sys_update_xml sys_ids to move (optional)","items":{"pattern":"^[0-9a-f]{32}$","type":"string"},"maxItems":200,"type":"array"},"source_update_set":{"description":"Filter by source update set name (e.g., \"Default\") (optional)","maxLength":255,"type":"string"},"table":{"default":"sys_update_xml","description":"Table name (default: sys_update_xml)","pattern":"^[A-Za-z0-9_]{1,80}$","type":"string"},"time_range":{"description":"Time range to filter records (optional - format: YYYY-MM-DD HH:MM:SS)","properties":{"end":{"description":"End time (e.g., \"2025-09-29 20:03:31\")","pattern":"^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}$","type":"string"},"start":{"description":"Start time (e.g., \"2025-09-29 20:00:00\")","pattern":"^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}$","type":"string"}},"type":"object"},"update_set_id":{"description":"Target update set sys_id to move records to (required)","pattern":"^[0-9a-f]{32}$","type":"string"}},"required":["update_set_id"],"type":"object"}"##;
pub(super) const CLONE_UPDATE_SET_DESC: &str = r##"Clone an entire update set with all its sys_update_xml records. Creates a complete copy for backup, testing, or branching development work. Reports progress during cloning operation."##;
